    #
    #       96c: bl   ml_wants_panic_trap_to_debugger     ; returns FALSE, the `beq` is taken
    #       9a0: bl   current_processor                   ; CPUDEBUGGERCOUNT++ -> 1
    #       9b8: cmp  r0, #6
    #       9bc: bcc  a14                                 ; TAKEN - 1 < NESTEDDEBUGGERENTRYMAX+1
    #       9c4: bl   PEHaltRestart                       ; NOT REACHED
