    OSFMK_KERN_KPC_THREAD_OBJ=${STAGE90_ENTRY_OSFMK_KERN_KPC_THREAD_OBJ:-$XNU_KERNEL_OBJ_OUT/osfmk_kern_kpc_thread.o}
