    #     xnu_entry_bss_start=0x80130a00             (unchanged)
    #     xnu_entry_bss_bytes=0x00036d98             (0x36dd8 -> 224664, as predicted)
    #     xnu_entry_copied_bytes=0x001309d4          (unchanged)
