    #     178: movw/movt r0, #_ZN8IOMapper7gSystemE ; mov r1,#2 ; str r1,[r0] ; pop {...pc}
    #     18c: ldr r0,[r5]                  ; fWaitLock
    #     198: bl lck_mtx_lock              ; IOLockLock is a MACRO - see below
    #     1a0: ... gSystem = 0 ...
    #     1b0: bl lck_mtx_unlock
    #     1c4: b  IOLockWakeup              ; tail call
