    require "$LIBKERN_OS_INTERNAL_OBJ" "run ./tools/build_xnu_arm_kernel.sh first"
    require "$IOKIT_KERNEL_IOSTARTIOKIT_OBJ" "run ./tools/build_xnu_arm_kernel.sh first"
