            read -r seam_endstores seam_endwfe <<<"$(awk '
                /^[[:space:]]*[0-9a-f]+:/ && $3 == "str" { s++ }
                /^[[:space:]]*[0-9a-f]+:/ && $3 == "wfe" { f++ }
