            stb_irq_decl="f98240dc f98240e4 f98240e8 f9824a0c"
            { read -r stb_irq_dev; read -r stb_irq_cnt; read -r stb_irq_img; read -r stb_irq_imgaddr; } < <(classify_body "$stb_irq_body" "$stb_irq_decl")
