                c2t_open_lns=$(awk '/bl.*<st_tout_open>/{ printf "%d ", NR }' <<<"$stb_path_body")
                c2t_restore_lns=$(awk '/bl.*<st_tout_restore>/{ printf "%d ", NR }' <<<"$stb_path_body")
                c2t_open_ln=${c2t_open_lns%% *}
