                gw_b_ln=$(awk '/bl.*<st_all_send_cid>/{ printf "%d", NR; exit }' <<<"$stb_path_body")
                gw_l_ln=$(awk '/bl.*<st_op_cond_loop>/{ printf "%d", NR; exit }' <<<"$stb_path_body")
