                    blk43_r1_off=$(grep -oE '#[0-9]+' <<<"$blk43_r1" | tail -1 | tr -d '#' || true)
                    blk43_r1_reg=$(grep -oE '\[r[0-9]+,' <<<"$blk43_r1" | grep -oE 'r[0-9]+' | head -1 || true)
