                    blk43_r1_lo=$(( $(grep -oE '#[0-9]+' <<<"$blk43_r1_w" | head -1 | tr -d '#') ))
                    blk43_r1_hi=$(( $(grep -oE '#[0-9]+' <<<"$blk43_r1_t" | head -1 | tr -d '#') ))
