                mi_st_dst=$(grep -oE 'str[[:space:]]+r[0-9]+, \[r[0-9]+\][[:space:]]*$' <<<"$mi_body" | head -1 | grep -oE 'r[0-9]+' | head -1 || true)
                [[ -n "$mi_st_dst" ]] ||
