                        function ispr(m) { return m ~ /^(ldr|str)(eq|ne|cs|hs|cc|lo|mi|pl|vs|vc|hi|ls|ge|lt|gt|le)$/ }
                        $1 ~ /^[0-9a-f]+:$/ {
                            a = strtonum("0x" substr($1, 1, length($1) - 1))
