                { read -r stb_nidx_s_dev; read -r stb_nidx_s_cnt; read -r stb_nidx_s_img; read -r stb_nidx_s_addr; } < <(classify_body "$stb_nidx_stripped" "$stb_nidx_decl")
                [[ -n "${stb_nidx_s_dev// /}" && "${stb_nidx_s_dev% }" == "$stb_nidx_s_want" ]] ||
